if (autoSyncMgr->mUpdateQ.Count() > 0) {
  if (!autoSyncMgr->mUpdateInProgress)  // Avoids possible overlap of updates
  {
    nsCOMPtr<nsIAutoSyncState> autoSyncStateObj(autoSyncMgr->mUpdateQ[0]);
    if (autoSyncStateObj) {
      int32_t state;
      nsresult rv = autoSyncStateObj->GetState(&state);
      if (NS_SUCCEEDED(rv) && (state == nsAutoSyncState::stCompletedIdle ||
                               state == nsAutoSyncState::stUpdateNeeded)) {
        nsCOMPtr<nsIMsgFolder> folder;
        autoSyncStateObj->GetOwnerFolder(getter_AddRefs(folder));
        if (folder) {
          // NOTE: this _should_ be protocol-agnostic, but we're not quite
          // there yet.
          // In both these cases, the autoSyncMgr is used as nsIUrlListener,
          // so nsAutoSyncManager::OnStopRunningUrl() will be invoked when
          // done.
          nsCOMPtr<nsIMsgImapMailFolder> imapFolder =
              do_QueryInterface(folder);
          if (imapFolder) {
            // IMAP. This will either UpdateFolder() immediately, or
            // issue a STATUS command to check message counts on the
            // server.
            rv = imapFolder->InitiateAutoSync(autoSyncMgr);
          } else {
            // Other types have no stStatusIssued phase, so just jump
            // straight to folder update.
            // To unify this, other protocols could be given a proper
            // status operation to check the message counts on the
            // server, or IMAP STATUS could be rolled up into its folder
            // update operation.
            rv = autoSyncStateObj->UpdateFolder();
          }
          if (NS_SUCCEEDED(rv)) {
            autoSyncMgr->mUpdateInProgress = true;
            NOTIFY_LISTENERS_STATIC(autoSyncMgr, OnAutoSyncInitiated,
                                    (folder));
          }
          MOZ_LOG_FMT(gAutoSyncLog, LogLevel::Debug,
                      "{}: process update q for folder={}", __func__,
                      folder->URI().get());
        } else {
          MOZ_LOG_FMT(
              gAutoSyncLog, LogLevel::Error,
              "{}: found an item in the update q, but the folder is null",
              __func__);
        }
      }
    }
  }
  // If initiation is not successful for some reason, or if there is an
  // ongoing download for this folder, remove it from q and continue with
  // the next one.
  if (!autoSyncMgr->mUpdateInProgress) {
    nsCOMPtr<nsIMsgFolder> folder;
    autoSyncMgr->mUpdateQ[0]->GetOwnerFolder(getter_AddRefs(folder));
    autoSyncMgr->mUpdateQ.RemoveObjectAt(0);

    if (folder) {
      NOTIFY_LISTENERS_STATIC(autoSyncMgr, OnFolderRemovedFromQ,
                              (nsIAutoSyncMgrListener::UpdateQueue, folder));
      MOZ_LOG_FMT(gAutoSyncLog, LogLevel::Error,
                  "{}: update q init failed for folder={}", __func__,
                  folder->URI().get());
    }
  }
